/* 对嵌入数据做校验和（练习时可在此函数下断点观察原始逻辑）*/
int blob_selfcheck(void) {
    unsigned int h = 0x811C9DC5u;
    int i;
    for (i = 0; i < (int)sizeof(g_blob); i++) {
        h ^= g_blob[i];
        h *= 0x01000193u;
    }
    return (int)(h & 0xFFFF);
}

/* 加载期自动执行（constructor），模拟真实库常见的初始化/反调试钩子 */
__attribute__((constructor)) static void _run_selfcheck(void) {
    (void)blob_selfcheck();
}
